// Plain helper, not a registered Convex function -- importing it from
// people.ts and captures.ts needs no _generated/api.d.ts patch.

import { MutationCtx } from "./_generated/server";

// Fixed-window per-user rate limiter backed by the rateLimits table. Not a
// sliding window: a caller right at a window boundary can burst up to
// 2x max, which is an acceptable trade for the denial-of-wallet threat
// model this exists to stop, in return for no extra bookkeeping.
//
// One row per (userId, action). A function with more than one window (e.g.
// a per-minute AND a per-day cap) calls this once per window with distinct
// action names, e.g. "createCapture:minute" and "createCapture:day".
export async function checkRateLimit(
  ctx: MutationCtx,
  userId: string,
  action: string,
  max: number,
  windowMs: number,
): Promise<void> {
  const now = Date.now();
  const existing = await ctx.db
    .query("rateLimits")
    .withIndex("by_user_action", (q) =>
      q.eq("userId", userId).eq("action", action),
    )
    .unique();

  if (existing === null) {
    await ctx.db.insert("rateLimits", {
      userId,
      action,
      windowStart: now,
      count: 1,
    });
    return;
  }

  if (now - existing.windowStart >= windowMs) {
    // Past the window: start a fresh one rather than accumulate forever.
    await ctx.db.patch("rateLimits", existing._id, {
      windowStart: now,
      count: 1,
    });
    return;
  }

  if (existing.count >= max) {
    throw new Error("Too many requests -- please wait a moment");
  }

  await ctx.db.patch("rateLimits", existing._id, {
    count: existing.count + 1,
  });
}

import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  people: defineTable({
    // Clerk's identity.tokenIdentifier ("issuer|subject"); the stable
    // ownership key now that there is no local users table.
    userId: v.string(),
    name: v.string(),
    link: v.optional(v.string()),
    context: v.optional(v.string()),
    updatedAt: v.number(),
    // Captured-from-screenshot provenance; all optional so hand-added
    // people need no migration.
    platform: v.optional(v.string()),
    handle: v.optional(v.string()),
    headline: v.optional(v.string()),
    screenshotId: v.optional(v.id("_storage")),
    // Semantic search. embeddedText doubles as the idempotency key so the
    // embed action can skip recomputing an unchanged person.
    embedding: v.optional(v.array(v.float64())),
    embeddedText: v.optional(v.string()),
  })
    .index("by_user", ["userId"])
    .searchIndex("search_name", {
      searchField: "name",
      filterFields: ["userId"],
    })
    .vectorIndex("by_embedding", {
      vectorField: "embedding",
      dimensions: 1536,
      filterFields: ["userId"],
    }),
  // A screenshot waiting to be triaged into a person. Deleted on accept
  // (the file moves to the person) or discard (the file is deleted too).
  captures: defineTable({
    userId: v.string(),
    screenshotId: v.id("_storage"),
    status: v.union(
      v.literal("pending"),
      v.literal("ready"),
      v.literal("failed"),
    ),
    extracted: v.optional(
      v.object({
        platform: v.string(),
        name: v.string(),
        handle: v.optional(v.string()),
        headline: v.optional(v.string()),
        bio: v.optional(v.string()),
      }),
    ),
    // Short, generic, user-safe message. Never the raw upstream text.
    error: v.optional(v.string()),
    // Raw upstream/error text for our own debugging. Never returned to a
    // client -- listCaptures and getCapture must not project this field.
    errorDetail: v.optional(v.string()),
  }).index("by_user", ["userId"]),
  // Fixed-window per-user rate limiting. One row per (userId, action) pair;
  // an action name like "createCapture:minute" models one window, so a
  // function with two windows (e.g. per-minute and per-day) gets two rows.
  rateLimits: defineTable({
    userId: v.string(),
    action: v.string(),
    windowStart: v.number(),
    count: v.number(),
  }).index("by_user_action", ["userId", "action"]),
});

